package com.lamggm.rospocket;
import android.app.Activity;
import android.content.Intent;
import android.net.Uri;
import android.os.Looper;
import android.widget.*;
import java.io.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @LooperMode(LooperMode.Mode.PAUSED)
public class RobotAssetsActivityTest {
 final RobotDashboardTest fixture=new RobotDashboardTest();MainActivity a;
 @Before public void setup()throws Exception{fixture.setup();a=fixture.f.a;fixture.tick(RobotDashboardTest.topics("/robot/robot_description"));}
 @After public void cleanup()throws Exception{fixture.cleanup();}
 Button button(){Button b=a.getWindow().getDecorView().findViewWithTag("robot-import-assets");assertNotNull("Native offline asset import must exist",b);return b;}
 String status(){return ((TextView)a.getWindow().getDecorView().findViewWithTag("robot-assets-status")).getText().toString();}
 void await(String text)throws Exception{long end=System.nanoTime()+5_000_000_000L;while(System.nanoTime()<end&&!status().startsWith(text)){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(10);}assertTrue(status(),status().startsWith(text));}
 void importBytes(byte[] bytes)throws Exception{button().performClick();var p=Shadows.shadowOf(a).getNextStartedActivityForResult();assertNotNull(p);Uri uri=Uri.parse("content://robot-assets-test/input");Shadows.shadowOf(a.getContentResolver()).registerInputStream(uri,new ByteArrayInputStream(bytes));a.onActivityResult(p.requestCode,Activity.RESULT_OK,new Intent().setData(uri));}
 @Test public void cancellationMalformedAndWrongDescriptionImportsPreserveExistingBytes()throws Exception{byte[] original=RobotAssetBundleTest.archive("meshes/base.glb",null,"robo_real");importBytes(original);await("Pacote importado");button().performClick();var picker=Shadows.shadowOf(a).getNextStartedActivityForResult();a.onActivityResult(picker.requestCode,Activity.RESULT_CANCELED,null);assertTrue(button().isEnabled());assertTrue(status().startsWith("Importação cancelada"));for(byte[] invalid:new byte[][]{new byte[]{1,2,3},RobotAssetBundleTest.archive("meshes/base.glb",null,"other")}){importBytes(invalid);await("Falha");assertArrayEquals(original,java.nio.file.Files.readAllBytes(new File(a.getFilesDir(),"robot-assets-v1.zip").toPath()));}}
 @Test public void destroyedOwnerCannotCommitLateProviderReply()throws Exception{byte[] bytes=RobotAssetBundleTest.archive("meshes/base.glb",null,"robo_real");java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);AtomicBoolean closed=new AtomicBoolean();InputStream delayed=new FilterInputStream(new ByteArrayInputStream(bytes)){public int read(byte[] b,int off,int n)throws IOException{entered.countDown();try{if(!release.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new IOException("test timeout");}catch(InterruptedException e){throw new IOException(e);}return super.read(b,off,n);}public void close()throws IOException{closed.set(true);super.close();}};button().performClick();var picker=Shadows.shadowOf(a).getNextStartedActivityForResult();Uri uri=Uri.parse("content://robot-assets-test/delayed");Shadows.shadowOf(a.getContentResolver()).registerInputStream(uri,delayed);a.onActivityResult(picker.requestCode,Activity.RESULT_OK,new Intent().setData(uri));try{assertTrue(entered.await(3,java.util.concurrent.TimeUnit.SECONDS));a.onDestroy();release.countDown();long end=System.nanoTime()+5_000_000_000L;while(System.nanoTime()<end&&!closed.get()){Thread.sleep(10);Shadows.shadowOf(Looper.getMainLooper()).idle();}assertTrue(closed.get());Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(new File(a.getFilesDir(),"robot-assets-v1.zip").exists());assertFalse(status().startsWith("Pacote importado"));}finally{release.countDown();}}
 @Test public void importsViaNativeDocumentPickerOffUiThreadAndSurvivesMetadataClear()throws Exception{assertTrue(button().isEnabled());button().performClick();var picker=Shadows.shadowOf(a).getNextStartedActivityForResult();assertNotNull(picker);assertEquals(Intent.ACTION_OPEN_DOCUMENT,picker.intent.getAction());assertTrue(picker.intent.hasCategory(Intent.CATEGORY_OPENABLE));byte[] bytes=RobotAssetBundleTest.archive("meshes/base.glb",null,"robo_real");AtomicBoolean onMain=new AtomicBoolean(),closed=new AtomicBoolean();InputStream stream=new FilterInputStream(new ByteArrayInputStream(bytes)){public int read(byte[] b,int off,int n)throws IOException{onMain.set(Looper.myLooper()==Looper.getMainLooper());return super.read(b,off,n);}public void close()throws IOException{closed.set(true);super.close();}};Uri uri=Uri.parse("content://robot-assets-test/valid");Shadows.shadowOf(a.getContentResolver()).registerInputStream(uri,stream);RobotPanel panel=(RobotPanel)fixture.f.get("robotPanel");panel.clear("Suspenso pelo seletor");a.onActivityResult(picker.requestCode,Activity.RESULT_OK,new Intent().setData(uri));await("Pacote importado");assertTrue(closed.get());assertFalse(onMain.get());assertTrue(new RobotAssetStore(a.getFilesDir()).load().matches(RobotDescription.parse(RobotDescriptionTest.SMALL)));fixture.tick(RobotDashboardTest.topics("/robot/robot_description"));assertTrue(((TextView)a.getWindow().getDecorView().findViewWithTag("robot-status")).getText().toString().contains("Modelo completo"));assertEquals(1,fixture.d.subscriptions);}
}
